    [11662]={name="Ban'thok Sash",quality=3,ilvl=54,reqLevel=49,sourceType="boss_drop",instructions="Drops from Ok'thor the Breaker.",zone="Blackrock Depths",npc="Ok'thor the Breaker",proc="Equip: Improves your chance to hit by 1.0%."},
