    [13958]={name="Wyrmthalak's Shackles",quality=3,ilvl=60,reqLevel=55,sourceType="quest_reward",instructions="Reward from the quest 'Warlord's Command'. Pick it over the other reward choices. Objective: Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",zone="Blackrock Spire",questName="Warlord's Command",lore="By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed: The rotund menace, Highlord Omokk. The cruel and ruthless troll, War Master Voone."},
