    [18102]={name="Dragonrider Boots",quality=3,ilvl=63,reqLevel=58,sourceType="boss_drop",instructions="Drops from Warchief Rend Blackhand.",npc="Warchief Rend Blackhand",lore="Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."},
